func (_Contract *ContractFilterer) ParseTranscriptAccepted(log types.Log) (*ContractTranscriptAccepted, error) {
	event := new(ContractTranscriptAccepted)
	if err := _Contract.contract.UnpackLog(event, "TranscriptAccepted", log); err != nil {
		return nil, err
	}
	event.Raw = log
	return event, nil
}
